import json,re,statistics
from pathlib import Path
p=Path('results/grpo_gsm8k')
ms=[json.loads(l) for l in (p/'metrics.jsonl').open()]
for k in ['critic/score/mean','response_length/mean','response_length/clip_ratio','actor/entropy','actor/grad_norm','actor/kl_loss','actor/pg_clipfrac','actor/ppo_kl','timing_s/step','response/aborted_ratio']:
 a=[r['data'][k] for r in ms if k in r['data']];print(k,'first10',statistics.mean(a[:10]),'last10',statistics.mean(a[-10:]),'range',min(a),max(a))
vs={s:[json.loads(l) for l in (p/f'val_generations/{s}.jsonl').open()] for s in [0,25,50]}
for s,rows in vs.items():
 print('VAL',s,len(rows),'score',sum(r['score'] for r in rows), 'keys',rows[0].keys())
 for long in [False,True]:
  a=[r for r in rows if (len(r['input'].split('user\\n')[1].split(\" Let's think\")[0])>500)==long]
  print('long',long,'n',len(a),'score',sum(r['score'] for r in a)/len(a),'chars',statistics.mean(len(r['output']) for r in a),'hash',sum('####' in r['output'] for r in a)/len(a))
for s in [1,25,50]:
 a=[json.loads(l) for l in (p/f'rollouts/{s}.jsonl').open()];print('ROLL',s,len(a),a[0].keys(),sum(r['score'] for r in a)/len(a))
